public String alienOrder(String[] words) {
    Map<Character, Set<Character>> adj = new HashMap<>();
    Map<Character, Integer> indeg = new HashMap<>();
    for (String w : words)
        for (char c : w.toCharArray()) {
            adj.putIfAbsent(c, new HashSet<>());
            indeg.putIfAbsent(c, 0);
        }
    for (int i = 0; i + 1 < words.length; i++) {
        String a = words[i], b = words[i + 1];
        int len = Math.min(a.length(), b.length());
        int j = 0;
        for (; j < len; j++) {
            char x = a.charAt(j), y = b.charAt(j);
            if (x != y) {
                if (adj.get(x).add(y)) indeg.merge(y, 1, Integer::sum);
                break;
            }
        }
        if (j == len && a.length() > b.length()) return ""; // invalid prefix
    }
    Deque<Character> q = new ArrayDeque<>();
    for (Map.Entry<Character, Integer> e : indeg.entrySet())
        if (e.getValue() == 0) q.offer(e.getKey());
    StringBuilder sb = new StringBuilder();
    while (!q.isEmpty()) {
        char u = q.poll();
        sb.append(u);
        for (char v : adj.get(u))
            if (indeg.merge(v, -1, Integer::sum) == 0) q.offer(v);
    }
    return sb.length() == indeg.size() ? sb.toString() : "";
}

public int minNumberOfSemesters(int n, int[][] relations, int k) {
    int[] pre = new int[n];                       // prereq mask per course
    for (int[] r : relations) pre[r[1] - 1] |= (1 << (r[0] - 1));

    int full = (1 << n) - 1;
    int[] dp = new int[1 << n];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    for (int mask = 0; mask <= full; mask++) {
        if (dp[mask] == Integer.MAX_VALUE) continue;
        int avail = 0;
        for (int c = 0; c < n; c++)
            if ((mask & (1 << c)) == 0 && (mask & pre[c]) == pre[c]) avail |= (1 << c);

        // enumerate all non-empty subsets of avail
        for (int sub = avail; sub > 0; sub = (sub - 1) & avail) {
            if (Integer.bitCount(sub) > k) continue;
            int next = mask | sub;
            dp[next] = Math.min(dp[next], dp[mask] + 1);
        }
    }
    return dp[full];
}

public int[] sortItems(int n, int m, int[] group, List<List<Integer>> beforeItems) {
    // assign unique groups to -1 items
    for (int i = 0; i < n; i++) if (group[i] == -1) group[i] = m++;

    List<List<Integer>> itemAdj = new ArrayList<>(), grpAdj = new ArrayList<>();
    int[] itemIn = new int[n], grpIn = new int[m];
    for (int i = 0; i < n; i++) itemAdj.add(new ArrayList<>());
    for (int i = 0; i < m; i++) grpAdj.add(new ArrayList<>());

    for (int i = 0; i < n; i++)
        for (int b : beforeItems.get(i)) {
            itemAdj.get(b).add(i); itemIn[i]++;
            if (group[b] != group[i]) { grpAdj.get(group[b]).add(group[i]); grpIn[group[i]]++; }
        }

    List<Integer> itemOrder = topo(itemAdj, itemIn, n);
    List<Integer> grpOrder  = topo(grpAdj, grpIn, m);
    if (itemOrder.isEmpty() || grpOrder.isEmpty()) return new int[0];

    // bucket items by group, preserving item topo order
    Map<Integer, List<Integer>> byGroup = new HashMap<>();
    for (int it : itemOrder) byGroup.computeIfAbsent(group[it], z -> new ArrayList<>()).add(it);

    int[] res = new int[n]; int idx = 0;
    for (int g : grpOrder)
        for (int it : byGroup.getOrDefault(g, new ArrayList<>())) res[idx++] = it;
    return res;
}

private List<Integer> topo(List<List<Integer>> adj, int[] indeg, int cnt) {
    Deque<Integer> q = new ArrayDeque<>();
    for (int i = 0; i < cnt; i++) if (indeg[i] == 0) q.offer(i);
    List<Integer> order = new ArrayList<>();
    while (!q.isEmpty()) {
        int u = q.poll(); order.add(u);
        for (int v : adj.get(u)) if (--indeg[v] == 0) q.offer(v);
    }
    return order.size() == cnt ? order : new ArrayList<>();   // empty = cycle
}

public boolean sequenceReconstruction(int[] org, List<List<Integer>> seqs) {
    int n = org.length;
    Map<Integer, List<Integer>> adj = new HashMap<>();
    Map<Integer, Integer> indeg = new HashMap<>();
    for (List<Integer> seq : seqs)
        for (int x : seq) {
            adj.putIfAbsent(x, new ArrayList<>());
            indeg.putIfAbsent(x, 0);
        }
    for (List<Integer> seq : seqs)
        for (int i = 0; i + 1 < seq.size(); i++) {
            int u = seq.get(i), v = seq.get(i + 1);
            adj.get(u).add(v);
            indeg.merge(v, 1, Integer::sum);
        }
    if (indeg.size() != n) return false;              // must cover exactly 1..n
    Deque<Integer> q = new ArrayDeque<>();
    for (Map.Entry<Integer, Integer> e : indeg.entrySet())
        if (e.getValue() == 0) q.offer(e.getKey());
    int idx = 0;
    while (!q.isEmpty()) {
        if (q.size() > 1) return false;               // not unique
        int u = q.poll();
        if (idx >= n || u != org[idx++]) return false; // diverges from org
        for (int v : adj.get(u))
            if (indeg.merge(v, -1, Integer::sum) == 0) q.offer(v);
    }
    return idx == n;
}

