    boolean[] land = new boolean[m * n];
    int count = 0;
    int[][] dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    List<Integer> res = new ArrayList<>();
    for (int[] p : positions) {
        int r = p[0], c = p[1], idx = r * n + c;
        if (land[idx]) { res.add(count); continue; }   // duplicate add
        land[idx] = true;
        count++;
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
