public int removeStones(int[][] stones) {
    int n = stones.length;
    int OFFSET = 10001;
    DSU dsu = new DSU(2 * OFFSET);
    Set<Integer> used = new HashSet<>();
    for (int[] s : stones) {
        int r = s[0], c = s[1] + OFFSET;
        dsu.union(r, c);
        used.add(r); used.add(c);
    }
    Set<Integer> roots = new HashSet<>();
    for (int x : used) roots.add(dsu.find(x));
    return n - roots.size();
