    boolean[][][] visited = new boolean[m][n][k + 1];
    int[][] dirs = {{0,1},{1,0},{0,-1},{-1,0}};
    Queue<int[]> q = new ArrayDeque<>();
    q.offer(new int[]{0, 0, k});
    visited[0][0][k] = true;
    int steps = 0;
    while (!q.isEmpty()) {
        int size = q.size();
        steps++;
        for (int i = 0; i < size; i++) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1], rem = cur[2];
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr < 0 || nc < 0 || nr >= m || nc >= n) continue;
                int nrem = rem - grid[nr][nc];
                if (nrem < 0 || visited[nr][nc][nrem]) continue;
                if (nr == m - 1 && nc == n - 1) return steps;
                visited[nr][nc][nrem] = true;
                q.offer(new int[]{nr, nc, nrem});
            }
        }
    }
    return -1;
}

public double maxProbability(int n, int[][] edges, double[] succProb, int start, int end) {
    List<double[]>[] adj = new List[n];
    for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
    for (int i = 0; i < edges.length; i++) {
        adj[edges[i][0]].add(new double[]{edges[i][1], succProb[i]});
        adj[edges[i][1]].add(new double[]{edges[i][0], succProb[i]});
    }
    double[] prob = new double[n];
    prob[start] = 1.0;
    PriorityQueue<double[]> pq = new PriorityQueue<>((a, b) -> Double.compare(b[1], a[1]));
    pq.offer(new double[]{start, 1.0});
    while (!pq.isEmpty()) {
        double[] cur = pq.poll();
        int u = (int) cur[0];
        double p = cur[1];
        if (u == end) return p;
        if (p < prob[u]) continue;
        for (double[] e : adj[u]) {
            int v = (int) e[0];
            double np = p * e[1];
            if (np > prob[v]) {
                prob[v] = np;
                pq.offer(new double[]{v, np});
            }
        }
    }
    return 0.0;
}

public int minCostConnectPoints(int[][] points) {
    int n = points.length;
    boolean[] inMST = new boolean[n];
    int[] minDist = new int[n];
    Arrays.fill(minDist, Integer.MAX_VALUE);
    minDist[0] = 0;
    int total = 0;
    for (int i = 0; i < n; i++) {
        int u = -1;
        for (int j = 0; j < n; j++) {
            if (!inMST[j] && (u == -1 || minDist[j] < minDist[u])) u = j;
        }
        inMST[u] = true;
        total += minDist[u];
        for (int v = 0; v < n; v++) {
            if (!inMST[v]) {
                int d = Math.abs(points[u][0] - points[v][0])
                      + Math.abs(points[u][1] - points[v][1]);
                if (d < minDist[v]) minDist[v] = d;
            }
        }
    }
    return total;
}

public int minimumCost(int n, int[][] connections) {
    Arrays.sort(connections, (a, b) -> a[2] - b[2]);
    int[] parent = new int[n + 1];
    for (int i = 0; i <= n; i++) parent[i] = i;
    int total = 0, used = 0;
    for (int[] c : connections) {
        int ra = find(parent, c[0]), rb = find(parent, c[1]);
        if (ra != rb) {
            parent[ra] = rb;
            total += c[2];
            used++;
        }
    }
    return used == n - 1 ? total : -1;
}

