public List<List<Integer>> findCriticalAndPseudoCriticalEdges(int n, int[][] edges) {
    int m = edges.length;
    int[][] e = new int[m][4];
    for (int i = 0; i < m; i++) e[i] = new int[]{edges[i][0], edges[i][1], edges[i][2], i};
    Arrays.sort(e, (a, b) -> a[2] - b[2]);

    int base = buildMST(n, e, -1, -1);
    List<Integer> critical = new ArrayList<>(), pseudo = new ArrayList<>();
    for (int i = 0; i < m; i++) {
        if (buildMST(n, e, i, -1) > base) {
            critical.add(e[i][3]);
        } else if (buildMST(n, e, -1, i) == base) {
            pseudo.add(e[i][3]);
        }
    }
    List<List<Integer>> res = new ArrayList<>();
    res.add(critical);
    res.add(pseudo);
    return res;
}

private int buildMST(int n, int[][] e, int skip, int force) {
    int[] parent = new int[n];
    for (int i = 0; i < n; i++) parent[i] = i;
    int weight = 0, count = 0;
    if (force != -1) {
        parent[find(parent, e[force][0])] = find(parent, e[force][1]);
        weight += e[force][2];
        count++;
    }
    for (int i = 0; i < e.length; i++) {
        if (i == skip) continue;
        int ra = find(parent, e[i][0]), rb = find(parent, e[i][1]);
        if (ra != rb) {
            parent[ra] = rb;
            weight += e[i][2];
            count++;
        }
    }
    return count == n - 1 ? weight : Integer.MAX_VALUE;
}

private int find(int[] parent, int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

private int timer = 0;

public List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
    List<Integer>[] adj = new List[n];
    for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
    for (List<Integer> c : connections) {
        adj[c.get(0)].add(c.get(1));
        adj[c.get(1)].add(c.get(0));
    }
    int[] disc = new int[n], low = new int[n];
    Arrays.fill(disc, -1);
    List<List<Integer>> bridges = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        if (disc[i] == -1) dfs(i, -1, adj, disc, low, bridges);
    }
    return bridges;
}

private void dfs(int u, int parent, List<Integer>[] adj,
                 int[] disc, int[] low, List<List<Integer>> bridges) {
    disc[u] = low[u] = timer++;
    boolean skippedParent = false;
    for (int v : adj[u]) {
        if (v == parent && !skippedParent) { skippedParent = true; continue; }
        if (disc[v] == -1) {
            dfs(v, u, adj, disc, low, bridges);
            low[u] = Math.min(low[u], low[v]);
            if (low[v] > disc[u]) bridges.add(Arrays.asList(u, v));
        } else {
            low[u] = Math.min(low[u], disc[v]);
        }
    }
}

public List<String> findItinerary(List<List<String>> tickets) {
    Map<String, PriorityQueue<String>> graph = new HashMap<>();
    for (List<String> t : tickets) {
        graph.computeIfAbsent(t.get(0), x -> new PriorityQueue<>()).offer(t.get(1));
    }
    LinkedList<String> route = new LinkedList<>();
    Deque<String> stack = new ArrayDeque<>();
    stack.push("JFK");
    while (!stack.isEmpty()) {
        String u = stack.peek();
        PriorityQueue<String> pq = graph.get(u);
        if (pq != null && !pq.isEmpty()) {
            stack.push(pq.poll());
        } else {
            route.addFirst(stack.pop());
        }
    }
    return route;
}

public int[][] validArrangement(int[][] pairs) {
    Map<Integer, Deque<Integer>> graph = new HashMap<>();
    Map<Integer, Integer> out = new HashMap<>(), in = new HashMap<>();
    for (int[] p : pairs) {
        graph.computeIfAbsent(p[0], k -> new ArrayDeque<>()).push(p[1]);
        out.merge(p[0], 1, Integer::sum);
        in.merge(p[1], 1, Integer::sum);
    }
    int start = pairs[0][0];
    for (int node : out.keySet()) {
        if (out.get(node) - in.getOrDefault(node, 0) == 1) {
            start = node;
            break;
        }
    }
    LinkedList<Integer> path = new LinkedList<>();
    Deque<Integer> stack = new ArrayDeque<>();
    stack.push(start);
    while (!stack.isEmpty()) {
        int u = stack.peek();
        Deque<Integer> nbrs = graph.get(u);
        if (nbrs != null && !nbrs.isEmpty()) {
            stack.push(nbrs.pop());
        } else {
            path.addFirst(stack.pop());
        }
    }
    int[][] res = new int[pairs.length][2];
    int idx = 0, prev = path.pollFirst();
    while (!path.isEmpty()) {
        int cur = path.pollFirst();
        res[idx][0] = prev;
        res[idx][1] = cur;
        idx++;
        prev = cur;
    }
    return res;
}

public int minMalwareSpread(int[][] graph, int[] initial) {
    int n = graph.length;
    int[] parent = new int[n];
    for (int i = 0; i < n; i++) parent[i] = i;
    for (int i = 0; i < n; i++)
        for (int j = i + 1; j < n; j++)
            if (graph[i][j] == 1) parent[find(parent, i)] = find(parent, j);

    int[] size = new int[n];
    for (int i = 0; i < n; i++) size[find(parent, i)]++;
    int[] infected = new int[n];
    for (int node : initial) infected[find(parent, node)]++;

    Arrays.sort(initial);
    int ans = initial[0], best = -1;
    for (int node : initial) {
        int root = find(parent, node);
        if (infected[root] == 1 && size[root] > best) {
            best = size[root];
            ans = node;
        }
    }
    return ans;
}

private int find(int[] parent, int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}
